\title{Strong Completeness of Sets of Natural Numbers:\\
Ordered Blocks, Congruence Obstructions,\\ and the Analytic Divergence Hypothesis}
\author{Aristotle}
\date{August 11, 2026}

\begin{document}
\maketitle

\begin{abstract}
A set $A \subseteq \N$ is \emph{complete} if every sufficiently large integer is a sum of
distinct elements of $A$, and \emph{strongly complete} if $A \setminus F$ is complete for
every finite $F$. We develop a structural theory of strong completeness. We prove an
\emph{initial-segment criterion}: $A$ is strongly complete if and only if every tail
$A \cap (k,\infty)$ is complete, so arbitrary finite deletions reduce to canonical ones. We
establish an \emph{ordered-block criterion}: if $A$ contains a sequence of pairwise ordered
finite blocks whose subset sums cover intervals $[\ell_k,h_k]$ satisfying a doubling condition
$2\ell_k \le h_k+1$ and an overlap condition $\ell_{k+1} \le h_k+1$, then $A$ is strongly
complete; specialising to dyadic blocks $A \cap (2^k,2^{k+1}]$ gives a scale-based criterion.
We then prove a sharp negative result: six elements in every large dyadic block do not suffice
even for completeness, the multiples of $3$ being a counterexample, so any purely
density-based dyadic criterion is impossible. On the positive side we prove a
\emph{backbone-and-residues criterion}, deduce a \emph{dilation principle}, and refute the
natural parity conjecture: $3\N \cup \{1,2\}$ is complete, has infinitely many odd elements,
and is not strongly complete. We prove that strong completeness forces infinitely many
elements outside $d\Z$ for every $d \ge 2$, and finally show that at every rational test point
$\theta = 1/d$ the divergence of $\sum_{a \in A}\|a\theta\|^2$ is \emph{equivalent} to that
congruence richness. Hence the analytic divergence hypothesis of the classical theory implies
the necessary congruence condition, every strongly complete set satisfies all of its rational
instances, and each of our counterexamples provably violates it.
\end{abstract}

\noindent\textbf{Keywords.} complete sequences; subset sums; strong completeness; dyadic
blocks; residue classes; distance to the nearest integer; divergence criteria.

\section{Introduction}

\subsection{Completeness and its fragility}

Let $\N = \{0,1,2,\dots\}$. A finite set $s \subseteq A$ has the \emph{subset sum}
$\sum_{a \in s} a$; since $s$ is a set, each element is used at most once.

\begin{definition}[Subset sum]
For $A \subseteq \N$ and $n \in \N$, write $n \in \Sig(A)$ and say $n$ is a \emph{subset sum
of $A$} if there is a finite set $s \subseteq A$ with $\sum_{a\in s} a = n$.
\end{definition}

\begin{definition}[Complete]
$A \subseteq \N$ is \emph{complete} if there is $N$ such that every $n \ge N$ lies in
$\Sig(A)$.
\end{definition}

Classical examples: the powers of two (for which $\Sig(A) = \N$ exactly), the squares (every
integer greater than $128$), the primes (every integer greater than $6$).

The property is delicate. Put $E_1 = \{2m : m \in \N\} \cup \{1\}$. Every even $n$ is a subset
sum, and every odd $n \ge 3$ equals $1 + (n-1)$ with $n-1$ even and distinct from $1$; so
$E_1$ is complete. But $E_1 \setminus \{1\} = 2\N$ has only even subset sums, so a single
deletion destroys completeness.

\begin{definition}[Strongly complete]
$A \subseteq \N$ is \emph{strongly complete} if $A \setminus F$ is complete for every finite
$F \subseteq \N$.
\end{definition}

Strong completeness implies completeness (take $F = \emptyset$), and $E_1$ shows the converse
fails.

\subsection{What this paper does}

The classical headline theorem asserts, roughly, that if from some point on each dyadic range
$(2^k,2^{k+1}]$ contains at least six elements of $A$, and if $\sum_{a \in A}\|a\theta\|^2 =
\infty$ for every non-integral real $\theta$ (with $\|x\|$ the distance from $x$ to the
nearest integer), then $A$ is strongly complete. We dissect this statement, isolating the
combinatorial engine, determining which hypotheses are removable, and giving the analytic
hypothesis an arithmetic reading. The organising slogan is: \emph{strong completeness requires
two mechanisms, each stable under finite deletion --- a size mechanism and a congruence
mechanism --- and neither alone suffices.}

\section{Elementary structure}

\begin{lemma}[Monotonicity]\label{lem:mono}
If $A \subseteq B$ and $n \in \Sig(A)$ then $n \in \Sig(B)$. Consequently, if $A$ is complete
so is $B$, and if $A$ is strongly complete so is $B$.
\end{lemma}

\begin{proof}
A witnessing finite $s \subseteq A$ also lies in $B$ with the same sum; the same threshold
works. For strong completeness use $A \setminus F \subseteq B \setminus F$.
\end{proof}

\begin{theorem}[Initial-segment criterion]\label{thm:tails}
$A \subseteq \N$ is strongly complete if and only if $A \cap (k,\infty)$ is complete for every
$k \in \N$.
\end{theorem}

\begin{proof}
($\Rightarrow$) Apply strong completeness with $F = [0,k]$, noting $A \setminus [0,k] =
A \cap (k,\infty)$.

($\Leftarrow$) A finite $F$ is bounded, say $F \subseteq [0,M]$. Then $A \cap (M,\infty)
\subseteq A \setminus F$, and the left side is complete by hypothesis, so Lemma~\ref{lem:mono}
makes $A \setminus F$ complete.
\end{proof}

Theorem~\ref{thm:tails} is the workhorse: to prove strong completeness it suffices to produce,
for each $k$, a completeness certificate using only elements of $A$ exceeding $k$.

\section{The ordered-block criterion}

\begin{definition}[Ordered block system]
A sequence $(B_k)_{k\ge0}$ of finite subsets of $\N$ is an \emph{ordered block system} if each
$B_k$ is nonempty and $x<y$ whenever $x \in B_k$, $y \in B_{k+1}$.
\end{definition}

\begin{theorem}[Ordered-block criterion]\label{thm:blocks}
Let $A \subseteq \N$ and let $(B_k)$ be an ordered block system with $B_k \subseteq A$ for all
$k$. Suppose there are sequences $(\ell_k)$, $(h_k)$ in $\N$ with
\begin{enumerate}
\item \textup{(coverage)} every $n$ with $\ell_k \le n \le h_k$ lies in $\Sig(B_k)$;
\item \textup{(positivity)} $\ell_k \ge 1$;
\item \textup{(monotonicity)} $\ell$ is nondecreasing;
\item \textup{(doubling)} $2\ell_k \le h_k + 1$;
\item \textup{(overlap)} $\ell_{k+1} \le h_k + 1$.
\end{enumerate}
Then $A$ is strongly complete; in particular $A$ is complete.
\end{theorem}

Overlap says consecutive covered intervals abut or overlap; doubling says each covered
interval is at least as long as its own left endpoint.

\begin{lemma}\label{lem:order}
In an ordered block system, $i<k$, $x \in B_i$, $y \in B_k$ imply $x<y$.
\end{lemma}

\begin{proof}
Induction on $k$. For $k=i+1$ this is the hypothesis. For the step, pick $z \in B_k$; then
$x<z$ by induction and $z<y$ by the consecutive-block hypothesis.
\end{proof}

\begin{lemma}\label{lem:size}
In an ordered block system, every $x \in B_k$ satisfies $x \ge k$.
\end{lemma}

\begin{proof}
Induction on $k$; the case $k=0$ is trivial. If all of $B_k$ is $\ge k$ and $y \in B_k$,
$x \in B_{k+1}$, then $x > y \ge k$, so $x \ge k+1$.
\end{proof}

\begin{proposition}[Block covering]\label{prop:cover}
Under the hypotheses of Theorem~\ref{thm:blocks}, fix $m$. For every $j \ge 0$, every integer
$n$ with $\ell_m \le n \le H_j := \sum_{i=0}^{j} h_{m+i}$ lies in
$\Sig\!\left(\bigcup_{i \le j} B_{m+i}\right)$.
\end{proposition}

\begin{proof}
Induction on $j$. For $j = 0$, $H_0 = h_m$ and coverage of $B_m$ applies.

For the step let $k := m+j+1$ and $\ell_m \le n \le H_j + h_k$.

\emph{Case A: $n \le H_j$.} Induction hypothesis.

\emph{Case B: $n > H_j$, $n \le h_k$.} Overlap at $m+j$ gives $\ell_k \le h_{m+j}+1 \le
H_j+1 \le n$, so $n \in [\ell_k,h_k]$ and coverage of $B_k$ applies.

\emph{Case C: $n > H_j$ and $n > h_k$.} We find $n = u+v$ with $\ell_m \le u \le H_j$ and
$\ell_k \le v \le h_k$. If $n \ge \ell_m + h_k$, take $v = h_k$, $u = n-h_k$; then
$u \ge \ell_m$ and $u \le H_j$, while $\ell_k \le h_k$ follows from doubling and
$\ell_k \ge 1$. If $n < \ell_m + h_k$, take $u = \ell_m$, $v = n - \ell_m$; then $v \le h_k$
and, from $n > h_k \ge 2\ell_k - 1$ together with $\ell_m \le \ell_k$ (monotonicity), one gets
$n \ge \ell_k + \ell_m$, i.e. $v \ge \ell_k$; also $u = \ell_m \le h_m \le H_j$ by doubling at
$m$.

Apply the induction hypothesis to $u$, giving $s_u$, and coverage to $v$, giving
$s_v \subseteq B_k$. By Lemma~\ref{lem:order} every element of $s_u$ is strictly smaller than
every element of $B_k$, so $s_u \cap s_v = \emptyset$ and
$\sum_{a \in s_u \cup s_v} a = u+v = n$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:blocks}]
Let $F \subseteq [0,M]$ be finite and $m := M+1$. By Lemma~\ref{lem:size}, every element of
$B_k$ with $k \ge m$ is $\ge k > M$, so those blocks avoid $F$. Doubling and positivity give
$h_k \ge 2\ell_k - 1 \ge 1$, whence $\sum_{i=0}^{n} h_{m+i} \ge n+1 > n$ for every $n$.
Proposition~\ref{prop:cover} with $j = n$ then represents every $n \ge \ell_m$ using blocks of
index $\ge m$, all inside $A \setminus F$. So $A \setminus F$ is complete with threshold
$\ell_m$.
\end{proof}

\subsection{Dyadic specialisation}

\begin{definition}[Dyadic block]
For $A \subseteq \N$, the $k$-th \emph{dyadic block} is $D_k(A) := A \cap (2^k,2^{k+1}]$.
\end{definition}

\begin{lemma}\label{lem:dyadic-partition}
Every $n \ge 2$ satisfies $2^k < n \le 2^{k+1}$ for exactly one $k$; the dyadic blocks
partition $A \cap [2,\infty)$.
\end{lemma}

\begin{proof}
Take $k$ maximal with $2^k < n$ (it exists as $2^0 < n$ and powers of two are unbounded);
maximality gives $n \le 2^{k+1}$. Uniqueness follows from strict monotonicity of $k\mapsto2^k$.
\end{proof}

\begin{theorem}[Full dyadic ranges]\label{thm:full-dyadic}
If there is $K$ with $(2^k,2^{k+1}] \subseteq A$ for every $k \ge K$, then $A$ is strongly
complete.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:blocks} with the paired blocks
$B_j := (2^{K+2j}, 2^{K+2j+2}] \cap \Z$ and $\ell_j := 2^{K+2j}+1$, $h_j := 2^{K+2j+2}$. Each
$B_j$ is the union of two consecutive full dyadic ranges, hence lies in $A$; it is nonempty;
blocks are ordered since $\max B_j = 2^{K+2j+2} < \min B_{j+1}$. Coverage is by singletons:
each $n \in [\ell_j,h_j]$ is itself an element of $B_j$. Doubling reads
$2^{K+2j+1}+2 \le 2^{K+2j+2}+1$, true since $2^{K+2j+2} = 2 \cdot 2^{K+2j+1} \ge
2^{K+2j+1}+2$. Overlap is the equality $\ell_{j+1} = h_j+1$.
\end{proof}

\begin{remark}
Pairing is essential: a single range $(2^k,2^{k+1}]$ covered by singletons has
$2\ell = 2^{k+1}+2 > h+1$ and fails doubling by exactly one.
\end{remark}

\section{Density is not enough}

\begin{definition}
$M_3 := \{n \in \N : 3 \mid n\}$.
\end{definition}

\begin{lemma}\label{lem:six}
For every $k \ge 5$, $D_k(M_3)$ contains at least six elements.
\end{lemma}

\begin{proof}
Since $k \ge 5$, $2^k \ge 32$. Let $c := 3(\lfloor 2^k/3 \rfloor + 1)$ be the least multiple of
$3$ exceeding $2^k$, so $2^k < c \le 2^k + 3$. The six numbers $c, c+3, \dots, c+15$ are
distinct multiples of $3$ above $2^k$ and $c+15 \le 2^k + 18 \le 2^k + 2^k = 2^{k+1}$.
\end{proof}

\begin{lemma}\label{lem:m3-incomplete}
$M_3$ is not complete.
\end{lemma}

\begin{proof}
All subset sums of multiples of $3$ are multiples of $3$; given a threshold $N$, the integer
$3N+1 \ge N$ is not one.
\end{proof}

\begin{theorem}[Six elements per dyadic block are insufficient]\label{thm:six-insufficient}
There is $A \subseteq \N$ with at least six elements in every dyadic block of index $\ge 5$
that is not complete, hence not strongly complete.
\end{theorem}

\begin{proof}
Take $A = M_3$ and combine Lemmas~\ref{lem:six} and~\ref{lem:m3-incomplete}.
\end{proof}

More generally, replacing $3$ by any $d$, the set $d\N$ has at least $c$ elements in every
dyadic block of index $k$ with $2^k \ge cd$, so no cardinality-based dyadic criterion can imply
completeness for any constant $c$. The auxiliary hypothesis of the classical theorem is
therefore mandatory: it must, at minimum, exclude subgroup obstructions.

\section{Backbones, residues, and the parity conjecture}

\begin{definition}
Let $d \ge 1$. A set $B \subseteq \N$ is \emph{complete mod $d$} if there is $N$ with
$dq \in \Sig(B)$ for all $q \ge N$, and a \emph{$d$-backbone} if $B \setminus F$ is complete
mod $d$ for every finite $F$.
\end{definition}

\begin{theorem}[Backbone-and-residues criterion]\label{thm:backbone}
Let $d \ge 1$ and $A \subseteq \N$. Suppose there is $B \subseteq A$ that is a $d$-backbone,
and that for every $r < d$ the set $\{a \in A : a \equiv r \pmod d\}$ is infinite. Then $A$ is
strongly complete.
\end{theorem}

\begin{proof}
Let $F \subseteq [0,M]$ be finite. For each $r<d$ choose $g(r) \in A$ with $g(r) \equiv r
\pmod d$ and $g(r) > M$; this is possible since infinitely many candidates exist. Put
$P := \max_{r<d} g(r)$.

Apply the backbone property to the finite set $F \cup [0,P]$: there is $N_1$ such that every
$dq$ with $q \ge N_1$ is a subset sum of $B \setminus (F \cup [0,P])$.

Let $n \ge P + dN_1 + 1$, put $r := n \bmod d$ and $a := g(r)$. Then $a \le P < n$ and
$a \equiv n \pmod d$, so $n-a = dq$ with $dq \ge n-P > dN_1$, hence $q \ge N_1$. Choose
$s \subseteq B \setminus (F \cup [0,P])$ summing to $dq$. Every element of $s$ exceeds
$P \ge a$, so $a \notin s$ and $\{a\}\cup s \subseteq A \setminus F$ consists of distinct
elements summing to $n$. Thus $A \setminus F$ is complete with threshold $P + dN_1+1$.
\end{proof}

The proof displays the two mechanisms: the single element $a$ fixes the residue (congruence
mechanism), the backbone handles the remaining multiple of $d$ (size mechanism). Both are
deletion-stable by hypothesis.

\begin{corollary}[Multiples and residues]\label{cor:mult-res}
Let $d \ge 1$. If $dm \in A$ for all $m \ge K$ and every residue class mod $d$ meets $A$
infinitely often, then $A$ is strongly complete.
\end{corollary}

\begin{proof}
Take $B := \{dm : m \ge K\}$. For finite $F \subseteq [0,M]$ and $q \ge \max(K,M+1)$ the
singleton $\{dq\} \subseteq B \setminus F$ sums to $dq$, so $B$ is a $d$-backbone. Apply
Theorem~\ref{thm:backbone}.
\end{proof}

\begin{theorem}
$\N$ is strongly complete.
\end{theorem}

\begin{proof}
For finite $F \subseteq [0,M]$ and $n \ge M+1$ the singleton $\{n\}$ works.
\end{proof}

\begin{theorem}[Dilation principle]\label{thm:dilation}
Let $d \ge 1$ and let $A$ be strongly complete. Then $d\cdot A := \{da : a \in A\}$ is a
$d$-backbone. Consequently $(d\cdot A) \cup C$ is strongly complete for any $C$ such that
$(d\cdot A)\cup C$ meets every residue class mod $d$ infinitely often.
\end{theorem}

\begin{proof}
Let $F$ be finite. As $a \mapsto da$ is injective, $F' := \{a : da \in F\}$ is finite; strong
completeness of $A$ gives $N$ with every $q \ge N$ a subset sum $\sum_{a\in s} a$ of
$A \setminus F'$. Then $\{da : a \in s\}$ consists of distinct elements of
$(d\cdot A)\setminus F$ summing to $dq$. The second claim is Theorem~\ref{thm:backbone}.
\end{proof}

\begin{corollary}[Evens plus infinitely many odds]\label{cor:evens}
If $A$ contains every even number and infinitely many odd numbers, then $A$ is strongly
complete.
\end{corollary}

\begin{proof}
Corollary~\ref{cor:mult-res} with $d = 2$, $K = 0$.
\end{proof}

Contrast $E_1 = 2\N \cup \{1\}$, which contains all evens and exactly one odd number and is
complete but not strongly complete: the dividing line is finiteness versus infinitude of the
residue-repair stock.

\subsection{Refutation of the parity conjecture}

\begin{definition}
$T := \{n \in \N : 3 \mid n\} \cup \{1,2\}$.
\end{definition}

\begin{lemma}\label{lem:T-complete}
$T$ is complete, with threshold $3$.
\end{lemma}

\begin{proof}
Let $n \ge 3$. If $3 \mid n$, then $\{n\}$ works. If $n \equiv 1 \pmod 3$, then $n-1$ is a
multiple of $3$ different from $1$, so $\{1,n-1\}$ works. If $n \equiv 2 \pmod 3$, then $n-2$
is a multiple of $3$ different from $2$, so $\{2,n-2\}$ works.
\end{proof}

\begin{lemma}\label{lem:T-odd}
$T$ contains infinitely many odd numbers.
\end{lemma}

\begin{proof}
$6k+3 = 3(2k+1)$ is an odd multiple of $3$ for every $k$, and $k \mapsto 6k+3$ is injective.
\end{proof}

\begin{lemma}\label{lem:T-notsc}
$T$ is not strongly complete.
\end{lemma}

\begin{proof}
$T \setminus \{1,2\} = M_3$, which is not complete by Lemma~\ref{lem:m3-incomplete}.
\end{proof}

\begin{theorem}[The parity conjecture is false]\label{thm:parity}
There is $A \subseteq \N$ that is complete, contains infinitely many odd elements, and is not
strongly complete.
\end{theorem}

\begin{proof}
Take $A = T$ and apply Lemmas~\ref{lem:T-complete}--\ref{lem:T-notsc}.
\end{proof}

Parity is only the instance $d=2$ of an obstruction indexed by all moduli: a set may be
complete solely because of finitely many elements escaping $d\Z$ for some $d \ne 2$.

\section{Congruence necessity and the analytic hypothesis}

\begin{theorem}[Congruence necessity]\label{thm:necessity}
If $A$ is strongly complete then, for every $d \ge 2$, the set
$A_d^{\times} := \{a \in A : d \nmid a\}$ is infinite.
\end{theorem}

\begin{proof}
If $A_d^\times$ were finite, delete it: $A \setminus A_d^\times \subseteq d\Z$, so all its
subset sums are divisible by $d$, and no $dN+1$ is a subset sum. This contradicts strong
completeness.
\end{proof}

\begin{definition}
For $x \in \R$ let $\{x\}$ be its fractional part and $\|x\| := \min(\{x\},1-\{x\})$ the
distance from $x$ to the nearest integer, so $0 \le \|x\| \le 1/2$ and $\|x\| = 0$ iff
$x \in \Z$.
\end{definition}

\begin{lemma}\label{lem:dist-lb}
If $d \ge 2$ and $d \nmid a$ then $\|a/d\| \ge 1/d$.
\end{lemma}

\begin{proof}
Write $a = qd+r$ with $1 \le r \le d-1$. Then $\{a/d\} = r/d \ge 1/d$ and
$1-\{a/d\} = (d-r)/d \ge 1/d$.
\end{proof}

\begin{definition}[Analytic divergence hypothesis]
$A$ satisfies the \emph{divergence hypothesis} if
\[
\sum_{a \in A} \|a\theta\|^2 = \infty \qquad \text{for every } \theta \in \R \setminus \Z .
\]
All terms are nonnegative, so the value in $[0,\infty]$ is independent of summation order.
\end{definition}

\begin{theorem}[Rational divergence dictionary]\label{thm:dictionary}
Let $A \subseteq \N$ and $d \ge 2$. Then
\[
\sum_{a \in A} \left\| \frac{a}{d} \right\|^2 = \infty
\quad \Longleftrightarrow \quad
\{a \in A : d \nmid a\} \text{ is infinite.}
\]
\end{theorem}

\begin{proof}
($\Leftarrow$) By Lemma~\ref{lem:dist-lb} each such $a$ contributes at least $1/d^2 > 0$;
infinitely many such terms make the sum infinite.

($\Rightarrow$) Contrapositive: if $S := \{a \in A : d\nmid a\}$ is finite, then every
$a \in A \setminus S$ has $a/d \in \Z$ and contributes $0$, so the sum equals the finite sum
over $S$, at most $|S|/4$.
\end{proof}

\begin{corollary}[Divergence excludes congruence obstructions]\label{cor:div-excl}
If $A$ satisfies the divergence hypothesis then $\{a \in A : d \nmid a\}$ is infinite for every
$d \ge 2$; i.e. $A$ automatically satisfies the condition of Theorem~\ref{thm:necessity}.
\end{corollary}

\begin{proof}
For $d \ge 2$ we have $\theta = 1/d \in (0,1)$, so $\theta \notin \Z$; apply
Theorem~\ref{thm:dictionary}.
\end{proof}

\begin{corollary}
Neither $M_3$ nor $T$ satisfies the divergence hypothesis.
\end{corollary}

\begin{proof}
Otherwise Corollary~\ref{cor:div-excl} with $d=3$ would give infinitely many elements not
divisible by $3$; $M_3$ has none and $T$ has exactly two.
\end{proof}

Thus our counterexamples do not contradict the classical theorem: they fail its analytic
hypothesis, and for exactly the reason the hypothesis exists.

\begin{corollary}[Strong completeness forces rational divergence]\label{cor:sc-div}
If $A$ is strongly complete then $\sum_{a \in A}\|a/d\|^2 = \infty$ for every $d \ge 2$.
\end{corollary}

\begin{proof}
Theorem~\ref{thm:necessity} followed by Theorem~\ref{thm:dictionary}.
\end{proof}

Corollary~\ref{cor:sc-div} shows the rational part of the divergence hypothesis is not a proof
artefact but a consequence of the conclusion it helps derive. The full hypothesis, quantified
over irrational $\theta$ as well, is a genuine strengthening ruling out equidistribution
failures invisible modulo any single integer.

\section{Algorithms}

\paragraph{Reachability.} The reachable set $R_N(A) = \Sig(A \cap [0,N]) \cap [0,N]$ is
computed by the distinct-summand knapsack recursion: start from $\{0\}$ and, for each
$a \in A$ with $a \le N$, replace $R$ by $R \cup (R+a)$ truncated at $N$. With bitmasks the
cost is $O(|A \cap [0,N]| \cdot N/w)$ word operations. The largest $n \le N$ outside $R_N(A)$
is an empirical completeness threshold; the procedure detects failure of completeness quickly.

\paragraph{Greedy block representation.} Proposition~\ref{prop:cover} is constructive: locate
the largest $k$ with $\ell_k \le n$; if $n \le h_k$ represent $n$ inside $B_k$; otherwise emit
$v := h_k$ (or $v := n - \ell_m$ when $n < \ell_m + h_k$) from $B_k$ and recurse on $n-v$ with
blocks of smaller index. Termination is by decreasing block index; distinctness of the emitted
summands follows from the ordering of the blocks.

\paragraph{Deletion-robust representation.} Theorem~\ref{thm:backbone} gives: compute
$r = n \bmod d$, take $a$ the least element of $A$ in class $r$ exceeding $\max F$, and
represent $n - a = dq$ within the backbone above the residue-representative ceiling. For the
standard backbone $d\N$ this yields the two-summand representation $n = a + dq$ in constant
time.

\section{Applications and interpretation}

\paragraph{Coin systems.} Reading $A$ as denominations usable once each, completeness says all
large amounts are exactly payable and strong completeness says this survives the loss of any
finite part of the stock. Corollary~\ref{cor:evens} gives a design principle: an inexhaustible
supply of residue-repair coins in every class is needed, not merely one of each.

\paragraph{Sharpness of density heuristics.} Theorem~\ref{thm:six-insufficient} cautions
against density heuristics: the multiples of $3$ have positive density and abundant local
representation, yet represent nothing outside a subgroup.

\paragraph{Fourier reading.} The quantity $\|a\theta\|$ measures how far $e^{2\pi i a\theta}$
is from $1$; divergence of $\sum_a \|a\theta\|^2$ says the characters of $A$ never concentrate
at a non-trivial frequency. Theorem~\ref{thm:dictionary} identifies the rational shadow of this
statement with non-containment in a proper subgroup.

\paragraph{Generators.} Theorem~\ref{thm:dilation} gives a recipe: dilate any strongly complete
set by $d$ and adjoin a sparse residue-repair set, producing strongly complete sets on
prescribed scales.

\section{Open problems}

\begin{problem}[Residue-rich completeness]
If $A$ is complete and, for every $m \ge 2$ and every residue $r$, the class $r \bmod m$
contains infinitely many elements of $A$, is $A$ strongly complete?
Theorem~\ref{thm:backbone} settles this whenever $A$ carries a backbone; the backbone-free case
requires extracting a deletion-stable size mechanism from completeness itself.
\end{problem}

\begin{problem}[Quantitative divergence upgrade]
Can the dyadic block-size constant be lowered from six if the divergence hypothesis is
strengthened quantitatively, e.g. to
$\sum_{a \in A,\, a \le x} \|a\theta\|^2 \gg (\log x)^{1+\varepsilon}$ uniformly in $\theta$?
Theorem~\ref{thm:six-insufficient} shows some hypothesis is needed at every block size.
\end{problem}

\begin{problem}[Necessity of irrational frequencies]
Corollary~\ref{cor:sc-div} shows the rational instances are necessary. Is there a strongly
complete $A$ and an irrational $\theta$ with $\sum_{a \in A}\|a\theta\|^2 < \infty$?
\end{problem}

\begin{problem}[Block-based characterisation]
Theorem~\ref{thm:blocks} is sufficient but not necessary. Is there a necessary and sufficient
block criterion, perhaps phrased on tails in the spirit of Theorem~\ref{thm:tails}?
\end{problem}

\begin{problem}[Optimal doubling constant]
Can $2\ell_k \le h_k+1$ be relaxed to $c\,\ell_k \le h_k+1$ with $1<c<2$ at the price of a
stronger overlap condition? Determine the admissible region in the doubling/overlap parameter
plane.
\end{problem}

\begin{problem}[Effective thresholds]
The backbone criterion yields the explicit threshold $P + dN_1 + 1$. What is the optimal
completeness threshold of $A \setminus F$ as a function of $\max F$?
\end{problem}

\section*{Summary of results}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
\textbf{Result} & \textbf{Statement} \\
\midrule
Monotonicity & Supersets inherit (strong) completeness. \\
Initial-segment criterion & Strongly complete $\iff$ every tail $A\cap(k,\infty)$ complete. \\
Ordered-block criterion & Doubling $+$ overlap $\Rightarrow$ strong completeness. \\
Dyadic specialisation & All of $(2^k,2^{k+1}]$ for large $k$ $\Rightarrow$ strongly complete. \\
Six-per-block insufficiency & $M_3$ has $\ge 6$ per dyadic block, is not complete. \\
Backbone-and-residues & $d$-backbone $+$ infinite residue classes $\Rightarrow$ strongly complete. \\
Dilation principle & $d\cdot A$ is a $d$-backbone when $A$ is strongly complete. \\
Evens plus odds & All evens $+$ infinitely many odds $\Rightarrow$ strongly complete. \\
Parity conjecture refuted & $3\N \cup \{1,2\}$ is a counterexample. \\
Congruence necessity & Strongly complete $\Rightarrow$ infinitely many $a$ with $d \nmid a$. \\
Rational dictionary & $\sum \|a/d\|^2 = \infty \iff \{a : d\nmid a\}$ infinite. \\
Necessity of rational divergence & Strongly complete $\Rightarrow$ divergence at each $1/d$. \\
\bottomrule
\end{tabular}
\end{center}

