"""Greedy representation from an ordered block system (doubling + overlap)."""

from __future__ import annotations

from typing import List, Optional, Sequence, Tuple


def check_hypotheses(
    blocks: Sequence[Sequence[int]], los: Sequence[int], his: Sequence[int]
) -> List[Tuple[str, bool]]:
    """Verify the five hypotheses of the ordered-block criterion on a prefix."""
    n = len(blocks)
    ordered = all(max(blocks[k]) < min(blocks[k + 1]) for k in range(n - 1))
    coverage = all(covers(blocks[k], los[k], his[k]) for k in range(n))
    positivity = all(lo >= 1 for lo in los)
    monotone = all(los[k] <= los[k + 1] for k in range(n - 1))
    doubling = all(2 * los[k] <= his[k] + 1 for k in range(n))
    overlap = all(los[k + 1] <= his[k] + 1 for k in range(n - 1))
    return [
        ("blocks pairwise ordered", ordered),
        ("coverage of [lo_k, hi_k]", coverage),
        ("positivity lo_k >= 1", positivity),
        ("monotonicity of lo", monotone),
        ("doubling 2*lo_k <= hi_k + 1", doubling),
        ("overlap lo_{k+1} <= hi_k + 1", overlap),
    ]


def covers(block: Sequence[int], lo: int, hi: int) -> bool:
    """Does every integer of [lo, hi] arise as a subset sum of `block`?"""
    mask = 1
    full = (1 << (hi + 1)) - 1
    for a in block:
        if 0 < a <= hi:
            mask |= (mask << a) & full
    return all((mask >> n) & 1 for n in range(lo, hi + 1))


def represent_in_block(n: int, block: Sequence[int]) -> Optional[List[int]]:
    """Exact subset of `block` summing to n, by pruned depth-first search."""
    if n == 0:
        return []
    items = sorted(block, reverse=True)
    suffix = [0] * (len(items) + 1)
    for i in range(len(items) - 1, -1, -1):
        suffix[i] = suffix[i + 1] + items[i]
    chosen: List[int] = []

    def rec(idx: int, rest: int) -> bool:
        if rest == 0:
            return True
        if idx >= len(items) or suffix[idx] < rest:
            return False
        if items[idx] <= rest:
            chosen.append(items[idx])
            if rec(idx + 1, rest - items[idx]):
                return True
            chosen.pop()
        return rec(idx + 1, rest)

    return chosen if rec(0, n) else None


def greedy_representation(
    n: int, blocks: Sequence[Sequence[int]], los: Sequence[int], his: Sequence[int]
) -> Optional[List[int]]:
    """Represent n as a sum of distinct elements taken from the ordered blocks.

    Mirrors the block-covering induction: peel off the highest usable block,
    take either the whole of its covered ceiling or the exact remainder, then
    recurse downward. At most one pass over the blocks, so O(K) block searches.
    """
    if n < los[0]:
        return None
    chosen: List[int] = []
    j = len(blocks) - 1
    while j >= 0 and n > 0:
        if los[j] <= n <= his[j]:
            part = represent_in_block(n, blocks[j])
            return None if part is None else sorted(chosen + part)
        if n > his[j]:
            part = represent_in_block(his[j], blocks[j])
            if part is None:
                return None
            chosen += part
            n -= his[j]
        j -= 1
    return sorted(chosen) if n == 0 else None


if __name__ == "__main__":
    K, nb = 2, 4
    blocks = [list(range(2 ** (K + 2 * j) + 1, 2 ** (K + 2 * j + 2) + 1)) for j in range(nb)]
    los = [2 ** (K + 2 * j) + 1 for j in range(nb)]
    his = [2 ** (K + 2 * j + 2) for j in range(nb)]
    for name, ok in check_hypotheses(blocks, los, his):
        print(f"{name:<30}{'OK' if ok else 'FAIL'}")
    for n in (23, 57, 200, 700, 1100):
        print(n, "=", greedy_representation(n, blocks, los, his))

"""Deletion-robust representation via a backbone plus residue repair."""

from __future__ import annotations

from typing import Callable, Dict, List, Optional


def residue_representatives(
    d: int, membership: Callable[[int], bool], above: int, search: int = 100_000
) -> Dict[int, int]:
    """One element of A in each residue class mod d, all exceeding `above`.

    This is the finite data the backbone criterion extracts from the hypothesis
    that every class mod d meets A infinitely often. Cost O(d + search).
    """
    reps: Dict[int, int] = {}
    x = above + 1
    steps = 0
    while len(reps) < d and steps < search:
        if membership(x):
            reps.setdefault(x % d, x)
        x += 1
        steps += 1
    if len(reps) < d:
        raise ValueError("residue stock exhausted inside the search window")
    return reps


def represent_robust(
    n: int,
    d: int,
    membership: Callable[[int], bool],
    backbone: Callable[[int, int], Optional[List[int]]],
    max_deleted: int,
) -> Optional[List[int]]:
    """Represent n as (one residue-repair element) + (a backbone multiple of d).

    `backbone(q, floor)` must return a set of distinct elements summing to d*q,
    all strictly above `floor`. The returned representation avoids every
    integer <= max_deleted, hence survives any deletion inside [0, max_deleted].
    Complexity: O(d + cost of one backbone call).
    """
    reps = residue_representatives(d, membership, max_deleted)
    ceiling = max(reps.values())
    a = reps[n % d]
    if a > n:
        return None
    rest = n - a
    if rest % d != 0:
        return None
    if rest == 0:
        return [a]
    tail = backbone(rest // d, ceiling)
    if tail is None:
        return None
    return sorted([a] + tail)


def singleton_backbone(d: int) -> Callable[[int, int], Optional[List[int]]]:
    """The canonical d-backbone: all multiples of d, represented by singletons."""

    def bb(q: int, floor: int) -> Optional[List[int]]:
        return [d * q] if d * q > floor else None

    return bb


if __name__ == "__main__":
    d = 5

    def member(x: int) -> bool:
        return x % d == 0 or x % (d * d) in {6, 12, 18, 24}

    for n in range(3000, 3006):
        print(n, "=", represent_robust(n, d, member, singleton_backbone(d), 200))
